// TapeGate demo UI — talks to the agent only (no wallet, no keys).
// Config comes from web/config.js (generated by scripts/demo.mjs);
// without it, defaults point at a locally running demo agent.
const CFG = (window.TAPEGATE_CONFIG || { agentBase: 'http://127.0.0.1:18080', vault: '(not deployed yet)', chainId: 196 });
const INPUTS = ['agentOK', 'budgetOK', 'notRevoked', 'windowOK', 'amountOK', 'fundedOK'];
const state = { inputs: 63 };

const $ = (id) => document.getElementById(id);

async function jget(p) { const r = await fetch(CFG.agentBase + p); return r.json(); }

// --- status ---
(async () => {
  try {
    const h = await jget('/health');
    const t = await jget('/tapeout');
    $('status').innerHTML =
      `Agent: <span class="ok">online</span> (mode ${h.mode}, agent ${h.agent || '—'})<br>` +
      `Vault: <code>${h.vault || CFG.vault}</code> · chain ${h.chainId}<br>` +
      `TapeOut processor TAPELIQUID: <code>${t.processor}</code> (#${t.processorIndex})`;
    $('tapeout').textContent =
      `TAPEOUT_FEE ${t.tapeoutFeeWei} wei (0.0013 OKB) · container FEE ${t.openFeeWei} wei (0.08 OKB)\n` +
      `Circuit: ${t.circuitName || '(identity circuit not taped out yet — see scripts/tapeout-identity.mjs)'}`;
  } catch (e) {
    $('status').innerHTML = `<span class="bad">Agent unreachable at ${CFG.agentBase}.</span> Start it with <code>node scripts/demo.mjs</code> (boots agent + fork) or <code>npm start</code> in <code>agent/</code>.`;
  }
})();

// --- circuit diagram (AND6 built from 10 NAND gates) ---
function draw() {
  const svg = $('diagram');
  const W = 820, H = 330;
  // Layout: 6 input rows on the left, 5 AND2 stages left-to-right.
  // Each AND2 = NAND gate + NOT gate (NAND with tied inputs).
  const rows = INPUTS.map((n, i) => ({ name: n, y: 30 + i * 50 }));
  const stages = [0, 1, 2, 3, 4]; // combine acc with input i+1
  let s = `<rect width="${W}" height="${H}" fill="#fff"/>`;
  const gate = (x, y, label) =>
    `<g><rect class="gate" x="${x}" y="${y}" width="64" height="30" rx="6"/>` +
    `<text x="${x + 32}" y="${y + 19}" text-anchor="middle">${label}</text></g>`;
  // Input labels + wires to first column.
  rows.forEach((r, i) => {
    const on = (state.inputs >> i) & 1;
    s += `<text x="8" y="${r.y + 5}" class="${on ? 'bit-on' : 'bit-off'}">${on} ${r.name}</text>`;
    s += `<line class="wire" x1="118" y1="${r.y}" x2="180" y2="${r.y}"/>`;
  });
  // Stage columns: x = 180, 300, 420, 540, 660. Each stage: NAND at y of acc, NOT below it.
  let accY = rows[0].y;
  const stageX = [180, 300, 420, 540, 660];
  for (let st = 0; st < 5; st++) {
    const x = stageX[st];
    const inY = rows[st + 1].y;
    const midY = (accY + inY) / 2;
    s += gate(x, midY - 15, 'NAND');
    s += gate(x, midY + 22, 'NOT');
    // wires: acc -> NAND top, input -> NAND bottom, NAND -> NOT, NOT -> next acc
    s += `<line class="wire" x1="${st === 0 ? 118 : stageX[st - 1] + 64}" y1="${accY}" x2="${x}" y2="${midY - 6}"/>`;
    s += `<line class="wire" x1="118" y1="${inY}" x2="${x}" y2="${midY + 6}"/>`;
    s += `<line class="wire" x1="${x + 32}" y1="${midY + 15}" x2="${x + 32}" y2="${midY + 22}"/>`;
    accY = midY + 37;
  }
  s += `<line class="wire" x1="724" y1="${accY}" x2="770" y2="${accY}"/>`;
  const out = state.inputs === 63 ? 1 : 0;
  s += `<text x="772" y="${accY + 5}" class="${out ? 'bit-on' : 'bit-off'}">OUT=${out}</text>`;
  svg.innerHTML = s;
}

function renderToggles() {
  $('toggles').innerHTML = INPUTS.map((n, i) => {
    const on = (state.inputs >> i) & 1;
    return `<label><input type="checkbox" data-bit="${i}" ${on ? 'checked' : ''}> ${n}</label>`;
  }).join('');
  $('toggles').querySelectorAll('input').forEach((el) => el.addEventListener('change', () => {
    const bit = Number(el.dataset.bit);
    state.inputs = el.checked ? state.inputs | (1 << bit) : state.inputs & ~(1 << bit);
    draw();
  }));
}
renderToggles();
draw();

// --- ask the agent ---
$('ask').addEventListener('click', async () => {
  const recipient = $('recipient').value.trim();
  const amountOkb = $('amount').value.trim();
  let amountWei;
  try { amountWei = (BigInt(Math.round(parseFloat(amountOkb) * 1e6)) * 10n ** 12n).toString(); }
  catch { $('decision').textContent = 'Bad amount.'; return; }
  const requestId = '0x' + [...crypto.getRandomValues(new Uint8Array(32))].map((b) => b.toString(16).padStart(2, '0')).join('');
  $('decision').textContent = 'Asking agent…';
  try {
    const r = await fetch(CFG.agentBase + '/decide', {
      method: 'POST', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ requestId, recipient, amount: amountWei, deadline: Math.floor(Date.now() / 1000) + 3600, inputs: state.inputs }),
    });
    const d = await r.json();
    $('decision').textContent = JSON.stringify(d, null, 2);
  } catch (e) {
    $('decision').textContent = 'Agent unreachable: ' + e.message;
  }
});
